  function sourceButtons(sources){return `<div class="ki-sources">${sources.map(d=>`<button class="ki-source" data-ki-action="source" data-id="${esc(d.id)}" ${state.busy?'disabled':''}><span>${esc(d.kind==='browser'?'Spaces · Browser':d.kind==='photo'?'Foto · lokale Texterkennung':d.kind==='miro'?'Miro':d.kind==='service'?({gitlab:'GitLab',sciebo:'Sciebo',mattermost:'Mattermost'})[d.service]||'Kursdienst':KNOWLEDGE_KINDS[d.kind]||'Quelle')} · ${esc(labels[d.status])}</span><strong>${esc(d.title)}</strong>${ageBadge(d)}<small>${d.kind==='browser'?'Original öffnen':'Quellenvorschau öffnen'} ↗</small></button>`).join('')}</div>`;}
  // Platform sources are often old: show their age so a stale source is never mistaken for a current one.
