      const bytes=new Uint8Array(await file.arrayBuffer());
      const digest=await crypto.subtle.digest('SHA-256',bytes),id='photo:'+Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
      const dataURL=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Das Foto konnte nicht geöffnet werden.'));reader.readAsDataURL(file);});
